/// lookup's comparisons are mostly the one that matches, where `==` would call `memcmp`.
#[inline]
pub fn key_eq(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    let n = a.len();
