        let answered = self.rpc.types_of_symbols(&unknown).await?;
        if answered.len() != unknown.len() {
            return Err(CallError::Rejected(format!(
                "getTypesOfSymbols answered {} types for {} symbols",
                answered.len(),
                unknown.len()
            )));
