async fn leave_to_layers(
    converter: &Converter,
    interner: &PropInterner,
    own: Vec<SymbolInfo>,
    whole: &[PropParent],
    target: &Target,
) -> Result<(Vec<SymbolInfo>, Vec<Option<Arc<SemanticProp>>>), CallError> {
